using AcxiomCRM.Data; using AcxiomCRM.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;
[Authorize] public class CustomersController:Controller { private readonly ApplicationDbContext _db; public CustomersController(ApplicationDbContext db)=>_db=db;
 public async Task<IActionResult> Index(string? search){var q=_db.Customers.AsQueryable(); if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.CustomerName.Contains(search)||x.Email.Contains(search)||x.Phone.Contains(search));return View(await q.OrderByDescending(x=>x.CustomerId).ToListAsync());}
 public IActionResult Create()=>View(); [HttpPost] public async Task<IActionResult>Create(Customer c){if(await _db.Customers.AnyAsync(x=>x.Email==c.Email||x.Phone==c.Phone))ModelState.AddModelError("","Email or phone already exists.");if(ModelState.IsValid){_db.Customers.Add(c);await _db.SaveChangesAsync();_db.AuditLogs.Add(new AuditLog{Action="Create",EntityName="Customer",RecordId=c.CustomerId.ToString(),UserId=User.Identity?.Name,Details=c.CustomerName});await _db.SaveChangesAsync();return RedirectToAction(nameof(Index));}return View(c);}
 public async Task<IActionResult>Edit(int id){var c=await _db.Customers.FindAsync(id);return c==null?NotFound():View(c);} [HttpPost] public async Task<IActionResult>Edit(int id,Customer c){if(id!=c.CustomerId)return NotFound();if(ModelState.IsValid){_db.Update(c);await _db.SaveChangesAsync();_db.AuditLogs.Add(new AuditLog{Action="Update",EntityName="Customer",RecordId=id.ToString(),UserId=User.Identity?.Name});await _db.SaveChangesAsync();return RedirectToAction(nameof(Index));}return View(c);}
 [HttpPost] public async Task<IActionResult>Delete(int id){var c=await _db.Customers.FindAsync(id);if(c!=null){c.Status="Inactive";await _db.SaveChangesAsync();_db.AuditLogs.Add(new AuditLog{Action="Delete/Deactivate",EntityName="Customer",RecordId=id.ToString(),UserId=User.Identity?.Name});await _db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}}
